CREATE TABLE t1(a text, b text, c text); WITH RECURSIVE seq(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM seq WHERE i<9999), s(v) AS (SELECT group_concat(x,'') FROM (SELECT substr('abcdefghijklmnopqrstuvwxyz',(i%26)+1,1)||' '||printf('%04d',i)||' ' AS x FROM seq ORDER BY i)) INSERT INTO t1 SELECT substr(v,1,65520),'abc','xyz' FROM s; INSERT INTO t1 VALUES('1','2','3'); INSERT INTO t1 VALUES('A','B','C'); CREATE INDEX i1 ON t1(a);